#nullable enable // autogenerated

using System.Linq;
using MVZ2.Resources;
using PVZEngine;

namespace MVZ2.ResourcePacks
{
    public class ModifiedCharacterSource : ITalkCharacterSource
    {
        public ModifiedCharacterSource(ITalkCharacterVariant[] variants, bool faceRight = false)
        {
            Variants = variants;
            FaceRight = faceRight;
        }

        public bool FaceRight { get; set; }
        public ITalkCharacterVariant[] Variants { get; }

        public ITalkCharacterVariant GetFirstVariant()
        {
            return Variants.First();
        }

        public ITalkCharacterVariant GetVariant(NamespaceID id)
        {
            return Variants.First(v => v.ID == id);
        }

        public ITalkCharacterVariant[] GetVariants()
        {
            return Variants;
        }
    }
}
